// Private owned-map inventory. No game content is embedded in this tool.
#include "original_archive.h"
#include "campaign_map.h"
#include <fstream>
#include <cstdio>
#include <sys/stat.h>
int main(int argc,char**argv){if(argc!=3)return 2;try{mkdir(argv[2],0700);puts("key,width,height,human,bytes,triggers");for(bool brood:{false,true}){data_loading::mpq_file<DiscReader> disc(a_string(argv[1])+(brood?"/BroodWar.mpq":"/StarCraft.mpq"));for(const char* race:{"terran","zerg","protoss"})for(unsigned number=0;number<=12;++number)for(const char* variant:{"","a","b"}){char key[64],path[160];std::snprintf(key,sizeof key,"%s%s%02u%s",brood?"exp":"",race,number,variant);std::snprintf(path,sizeof path,"campaign/%s%s/%s%02u%s/staredit/scenario.chk",brood?"exp":"",race,race,number,variant);a_vector<uint8_t> chk;if(!extract(disc,path,chk))continue;unsigned w=0,h=0,human=12,triggers=0;for(size_t at=0;at+8<=chk.size();){unsigned n=port3ds::campaign::get(chk.data()+at+4);if(n>chk.size()-at-8)throw std::runtime_error("CHK bounds");auto* p=chk.data()+at+8;if(!memcmp(chk.data()+at,"DIM ",4) && n==4){w=p[0]|p[1]<<8;h=p[2]|p[3]<<8;}if(!memcmp(chk.data()+at,"TRIG",4))triggers=n/2400;if(!memcmp(chk.data()+at,"OWNR",4))for(unsigned i=0;i<8 && i<n;++i)if(p[i]==6){if(human!=12)throw std::runtime_error("Multiple human owners");human=i;}at+=8+n;}std::string out=std::string(argv[2])+"/"+key;{std::ofstream f(out+".raw.chk",std::ios::binary);f.write((char*)chk.data(),chk.size());}if(human<8){port3ds::campaign::normalize(chk,human);std::ofstream f(out+".chk",std::ios::binary);f.write((char*)chk.data(),chk.size());}printf("%s,%u,%u,%u,%zu,%u\n",key,w,h,human,chk.size(),triggers);}}}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
